import{_ as r,a as t,b as i}from"./chunks/scharf-36-punkte.BEa8JeOG.js";import{_ as n,o as a,c as s,ah as h}from"./chunks/framework.DDXs_i7t.js";const k=JSON.parse('{"title":"05. März: Der Tag der Wahrheit – Christa Scharf im Zeugenstand","description":"Showdown am Landesgericht Linz. Die unbestechliche Finanzbeamtin Dr. Christa Scharf sagt heute gegen das System des Postenschachers aus.","frontmatter":{"title":"05. März: Der Tag der Wahrheit – Christa Scharf im Zeugenstand","description":"Showdown am Landesgericht Linz. Die unbestechliche Finanzbeamtin Dr. Christa Scharf sagt heute gegen das System des Postenschachers aus.","date":"2026-03-05T00:00:00.000Z"},"headers":[],"relativePath":"logbuch/2026-03-05-showdown-christa-scharf.md","filePath":"logbuch/2026-03-05-showdown-christa-scharf.md"}'),d={name:"logbuch/2026-03-05-showdown-christa-scharf.md"};function o(u,e,g,l,c,m){return a(),s("div",null,[...e[0]||(e[0]=[h('<h1 id="⚖️-05-marz-der-tag-der-wahrheit-–-christa-scharf-im-zeugenstand" tabindex="-1">⚖️ 05. März: Der Tag der Wahrheit – Christa Scharf im Zeugenstand <a class="header-anchor" href="#⚖️-05-marz-der-tag-der-wahrheit-–-christa-scharf-im-zeugenstand" aria-label="Permalink to &quot;⚖️ 05. März: Der Tag der Wahrheit – Christa Scharf im Zeugenstand&quot;">​</a></h1><p>Es ist <strong>Donnerstag, 06:45 Uhr</strong>. In wenigen Stunden wird am Landesgericht Linz ein Moment der Wahrheit stattfinden, auf den wir im Rahmen des <em>„Horten-Mysteriums“</em> seit Monaten hinarbeiten.</p><p>Über <strong>42.000 Menschen</strong> haben in den letzten 48 Stunden auf Reddit die „Harte Prosa“ von August Wöginger gesehen. Heute wird diese Prosa mit der <strong>harten Realität</strong> konfrontiert.</p><h3 id="was-heute-auf-dem-spiel-steht" tabindex="-1"><strong>Was heute auf dem Spiel steht:</strong> <a class="header-anchor" href="#was-heute-auf-dem-spiel-steht" aria-label="Permalink to &quot;**Was heute auf dem Spiel steht:**&quot;">​</a></h3><p>Heute tritt <strong>Dr. Christa Scharf</strong> in den Zeugenstand. Sie ist mehr als nur eine Zeugin; sie ist das moralische Herzstück unserer Mockumentary. Während die Gegenseite von „Bürgeranliegen“ und „Regionalpolitik“ spricht, bringt Scharf die Sprache der Fakten mit:</p><ul><li><strong>98 Punkte</strong> (Scharf) gegen <strong>62 Punkte</strong> (ÖVP-Bürgermeister).</li><li>Integrität gegen Intervention.</li><li>Qualifikation gegen Parteibuch.</li></ul><h3 id="die-asthetik-des-widerstands" tabindex="-1"><strong>Die Ästhetik des Widerstands</strong> <a class="header-anchor" href="#die-asthetik-des-widerstands" aria-label="Permalink to &quot;**Die Ästhetik des Widerstands**&quot;">​</a></h3><p>Wir dokumentieren diesen Tag als zentrales Motiv für <strong>Teil 4: Die politische Liebesgeschichte</strong>. In unserer filmischen Aufarbeitung kontrastieren wir die kühle, mathematische Präzision von Christa Scharf (inspiriert durch ihren Hintergrund im „Mamlinger Musiksommer“) mit der schwammigen Rhetorik der Macht.</p><blockquote><p><em>„Eine Zither verzeiht keinen falschen Griff. Der Rechtsstaat auch nicht.“</em> — Auszug aus dem Drehbuch, Szene 55.</p></blockquote><h3 id="live-begleitung-im-archiv-des-schweigens" tabindex="-1"><strong>Live-Begleitung im Archiv des Schweigens</strong> <a class="header-anchor" href="#live-begleitung-im-archiv-des-schweigens" aria-label="Permalink to &quot;**Live-Begleitung im Archiv des Schweigens**&quot;">​</a></h3><p>Wir werden den heutigen Tag forensisch begleiten. Jeder Satz, der heute in Linz fällt, wird von uns auf seinen Wahrheitsgehalt im Kontext des <strong>Pointillismus des Geldes</strong> geprüft.</p><p><strong>Bleiben Sie dran. Das Schweigen wird heute gebrochen.</strong></p><h3 id="🛑-update-13-45-uhr-–-die-aussage-der-beamtin" tabindex="-1">🛑 UPDATE: 13:45 Uhr – Die Aussage der Beamtin <a class="header-anchor" href="#🛑-update-13-45-uhr-–-die-aussage-der-beamtin" aria-label="Permalink to &quot;🛑 UPDATE: 13:45 Uhr – Die Aussage der Beamtin&quot;">​</a></h3><p>Der Vormittag am Landesgericht Linz war von einer beeindruckenden Ruhe und Präzision geprägt. Dr. Christa Scharf hat ihre Zeugenaussage beendet. Ihre wichtigste Botschaft des Tages:</p><blockquote><p><em>„Es geht mir nicht um die Entschädigung. Es geht um das <strong>Zurechtrücken</strong> dieser Geschichte.“</em></p></blockquote><p>Während die Verteidigung versuchte, ihre Leistung im Hearing kleinzureden (Stichwort „Nervosität“), blieb Scharf bei den harten Fakten ihrer Qualifikation.</p><p><strong>Was jetzt passiert:</strong></p><ul><li>Am Nachmittag wird der ÖVP-Bürgermeister Michael L. (der „62-Punkte-Kandidat“) vernommen.</li><li>Die Verhandlung ist bis 20:00 Uhr angesetzt – wir dokumentieren weiter!</li></ul><h3 id="🛑-update-18-30-uhr-–-das-„zusammenrucken-der-logik" tabindex="-1">🛑 UPDATE: 18:30 Uhr – Das „Zusammenrücken“ der Logik <a class="header-anchor" href="#🛑-update-18-30-uhr-–-das-„zusammenrucken-der-logik" aria-label="Permalink to &quot;🛑 UPDATE: 18:30 Uhr – Das „Zusammenrücken“ der Logik&quot;">​</a></h3><p>Der Nachmittag in Saal 114 bot den erwarteten, harten Kontrast. Michael L., der Nutzniesser der Intervention (62 Punkte), versuchte seine Bestellung als „Akt der regionalen Vernunft“ darzustellen.</p><p><strong>Die Highlights der Einvernahme:</strong></p><ul><li><strong>Die 36-Punkte-Lücke:</strong> Auf die Frage des Richters, wie er sich den massiven Punktabstand zu Dr. Scharf erkläre, antwortete L.: <em>„Man muss das Ganze sehen. Ein Finanzamt ist kein Taschenrechner. Da geht’s um das Gespür für die Leut&#39;.“</em></li><li><strong>Das „Bürgeranliegen“:</strong> L. bestätigte indirekt, dass er sich bei Wöginger „informiert“ habe, ob seine Bewerbung „eh passt“. Er nannte es ein <em>„ganz normales Gespräch unter Gemeindebürgern“</em>.</li></ul><h3 id="visualisierung-der-36-punkte-abgrund" tabindex="-1"><strong>Visualisierung: Der 36-Punkte-Abgrund</strong> <a class="header-anchor" href="#visualisierung-der-36-punkte-abgrund" aria-label="Permalink to &quot;**Visualisierung: Der 36-Punkte-Abgrund**&quot;">​</a></h3><p>Um die Absurdität dieses Moments zu verdeutlichen, haben wir für die Mockumentary eine Infografik erstellt, die den Kontrast zwischen Qualifikation und „Gespür“ visualisiert:</p><p><img src="'+r+'" alt="Der 36-Punkte-Abgrund: 98 vs 62"></p><p><em>Grafik: Der Pointillismus der Qualifikation. Links die sterile Präzision (Scharf), rechts der verschwommene „Bürgermeister-Faktor“ (Michael L.).</em></p><hr><h3 id="analyse-fur-die-mockumentary-„harte-prosa-vs-„harte-fakten" tabindex="-1"><strong>Analyse für die Mockumentary: „Harte Prosa“ vs. „Harte Fakten“</strong> <a class="header-anchor" href="#analyse-fur-die-mockumentary-„harte-prosa-vs-„harte-fakten" aria-label="Permalink to &quot;**Analyse für die Mockumentary: „Harte Prosa“ vs. „Harte Fakten“**&quot;">​</a></h3><p>Diese Konfrontation ist pures Gold für <strong>Teil 4: Die politische Liebesgeschichte</strong>. Wir haben heute gesehen, wie die Sprache der <strong>Harten Prosa</strong> (Wöginger/L.) versucht, die <strong>mathematische Realität</strong> (Scharf) zu übertönen.</p><p>In der filmischen Umsetzung werden wir diesen Moment als <strong>„Pointillismus der Verantwortung“</strong> inszenieren: Viele kleine Gefallen (Punkte), die am Ende ein Bild der Ungerechtigkeit ergeben.</p><p><strong>Exklusiv-Vorschau (Audio-Teaser):</strong> Hören Sie hier den ersten Entwurf der Szene 10c („Der 36-Punkte-Abgrund“) mit den KI-gestützten Stimmen von August Diehl und Birgit Minichmayr.</p><div style="background:#1a1a1a;padding:20px;border-radius:10px;border:1px solid #d4af37;margin:20px 0;"><p style="color:#d4af37;margin-top:0;"><b>🎙️ August Diehl (Erzähler)</b></p><audio controls style="width:100%;"><source src="'+t+'" type="audio/mpeg"> Ihr Browser unterstützt das Audio-Element nicht. </audio><p style="color:#d4af37;margin-top:20px;"><b>🎙️ Birgit Minichmayr (Christa Scharf)</b></p><audio controls style="width:100%;"><source src="'+i+'" type="audio/mpeg"> Ihr Browser unterstützt das Audio-Element nicht. </audio></div><blockquote><p><em>&quot;Ein Finanzamt ist kein Taschenrechner? Nein, es ist die Bühne für ein abgekartetes Spiel.&quot;</em></p></blockquote><hr><p><strong>Morgen, Freitag (06.03.):</strong></p><ul><li><strong>Reddit-Offensive:</strong> Zusammenfassung der Zeugenaussagen für r/Austria mit der neuen Infografik.</li><li><strong>Video-Release:</strong> Finaler Schnitt des Teasers für Teil 4 inklusive der „Taschenrechner“-Szene.</li></ul><p>👉 <a href="/recherche/gericht-woeginger-scharf.html">Zum detaillierten Prozess-Update im Archiv</a> 👉 <a href="/orakel.html">Das Pointillismus-Orakel befragen</a></p><hr><p><em>Berichterstattung vom 05. März 2026, 18:30 Uhr. Die Verhandlung wird vertagt.</em></p>',39)])])}const b=n(d,[["render",o]]);export{k as __pageData,b as default};
